import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    data = json.loads(json_data)
    if not isinstance(data, list) or not data:
        raise ValueError("Invalid JSON data")
    for entry in data:
        if not isinstance(entry, dict):
            raise ValueError("Invalid JSON data")
        if "Country" not in entry or "Population" not in entry:
            raise ValueError("Invalid JSON data")
        if not isinstance(entry["Country"], str):
            raise ValueError("Invalid JSON data")
        if not isinstance(entry["Population"], (int, float)) or entry["Population"] < 0:
            raise ValueError("Invalid JSON data")
    df = pd.DataFrame(data, columns=["Country", "Population"])
    df["Population"] = df["Population"].apply(math.floor)
    os.makedirs(output_dir, exist_ok=True)
    file_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(file_path, index=False)
    except Exception as e:
        raise IOError(f"Cannot write to file: {e}")
    return file_path, df

